using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;using MapTunnels;
public static class Root219Field{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence219");
 [Serializable]class Inputs{public string before,after;}[Serializable]class LoadRow{public string stage;public int count,visible,meshes,materials,textures,triangles;public long meshBytes;public double cpuMedianMs;}
 [Serializable]class Report{public bool pass,other19Exact,other19AtlasShared,prefabReload,sceneReload,boundsExact,colliderUnchanged;public int formalBefore,formalAfter,placedBefore,placedAfter,triBefore,triAfter;public string beforeFolder,afterFolder;public LoadRow[] loads;public string[] limits;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.13f,.14f,.15f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;Shader.SetGlobalVector("_TDPineWind",Vector4.zero);}
 static Camera Cam(){var c=new GameObject("root218-offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.035f,.04f,.045f);c.fieldOfView=45;c.nearClipPlane=.025f;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;return c;}
 static void Shot(Camera c,string name){var t=Shared117Review.Image(c,1100,800);File.WriteAllBytes(Path.Combine(Out,name+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 static string Snap(GameObject root){return string.Join("\n",root.GetComponentsInChildren<MeshFilter>().OrderBy(x=>x.name).Select(x=>x.name+"|"+x.transform.localPosition.ToString("F7")+"|"+x.transform.localRotation.ToString("F7")+"|"+x.transform.localScale.ToString("F7")+"|"+ColliderSnapshot109.MeshHash(x.sharedMesh)+"|"+JsonUtility.ToJson(new MeshData{n=x.sharedMesh.normals,uv=x.sharedMesh.uv,c=x.sharedMesh.colors})+"|"+AssetDatabase.GetAssetPath(x.GetComponent<Renderer>().sharedMaterial)+"|"+x.GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")));}
 [Serializable]class MeshData{public Vector3[] n;public Vector2[] uv;public Color[] c;}
 public static void Run(){Directory.CreateDirectory(Out);try{Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
var before=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 45/cnd008.prefab");var after=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 46/cnd008.prefab");Check(before&&after,"saved formal prefabs");Check(before.GetComponent<MeshFilter>().sharedMesh.triangles.Length==174&&after.GetComponent<MeshFilter>().sharedMesh.triangles.Length==504,"formal58/168");
FieldPair(before,after);File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"savedPrefabBefore\":\"Pilot 45/cnd008\",\"savedPrefabAfter\":\"Pilot 46/cnd008\",\"sameProductAs217\":true,\"sameMineLights\":true,\"scope\":\"Target placement and paired field render only; formal reload checks are Evidence219\"}");Empty();AssetDatabase.SaveAssets();Debug.Log("Root219 field completed; returning to standard -quit shutdown.");
}catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static string LampState(GameObject root){return string.Join("|",root.GetComponentsInChildren<Light>().Select(l=>l.transform.position.ToString("F7")+":"+l.intensity+":"+l.range+":"+l.color))+"/"+string.Join("|",root.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Select(m=>m.name+":"+m.GetFloat("_Emission")+":"+m.GetFloat("_Shaft")));}
 static void FieldPair(GameObject before,GameObject after){Empty();RenderSettings.ambientLight=new Color(.08f,.09f,.10f);var tunnel=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Root219Pair");Check(tunnel.built,"existing mine");var timber=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 26/small-mine_timber_frame.prefab");Check(timber,"existing timber prefab");var support=(GameObject)PrefabUtility.InstantiatePrefab(timber);support.transform.position=new Vector3(12,0,10.5f);
  var c=Cam();var hero=new GameObject("anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=tunnel.root.GetComponent<MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;
  var lamps=LampState(tunnel.root);File.WriteAllText(Path.Combine(Out,"mine-lights.txt"),lamps);
  foreach(string stage in new[]{"before","after"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(stage=="before"?before:after);o.transform.position=new Vector3(11.35f,2.51f,9.6f);o.transform.rotation=Quaternion.identity;
   foreach(string view in new[]{"normal","close","opposite"}){var target=o.transform.position+Vector3.down*.65f;c.transform.position=view=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(view=="opposite"?new Vector3(1.25f,-.16f,.3f):new Vector3(1.25f,-.16f,-1.1f));c.transform.LookAt(target);if(view=="normal")typeof(MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);else Shader.SetGlobalVector("_MapCutA",Vector4.zero);Check(LampState(tunnel.root)==lamps,"identical static mine lamps and materials");Shot(c,stage+"-mine-"+view);}
   UnityEngine.Object.DestroyImmediate(o);
  }
  Check(LampState(tunnel.root)==lamps,"lamps after pair");
 }
}
